const GOVERNANCE_AI_CHATS=Object.freeze({
  Claude:"https://claude.ai/new",
  ChatGPT:"https://chatgpt.com/",
  Perplexity:"https://www.perplexity.ai/",
  Kimi:"https://www.kimi.com/"
});
function newGovernanceState(){return{personaId:"",readiness:null,review:null,reviewManifest:null,reviewBaseline:null,featureRequests:[],syncSettings:[],friendSettings:null,extensions:[],roles:[],security:null,relationships:[],familyEdges:[],projects:[],businesses:[],revenueSettings:null,affiliateProducts:[],affiliateOffers:[],productReviewSettings:null,productReviewRequests:[],productReviewEvents:[],productReviewEvidence:[],assignedAccounts:[],staffRequests:[],staffExtensions:[],intentionPlan:null,intentionAiExplanation:"",capabilities:{governance:true,organization:true,revenue:true,reviewInbox:true}}}
let governanceState=newGovernanceState();
function resetGovernanceState(){governanceState=newGovernanceState()}

function governancePersona(id=""){
  return (myPersonas||[]).find(persona=>persona.id===(id||governanceState.personaId))||(myPersonas||[])[0]||null;
}

function governancePersonaOptions(selected){
  return (myPersonas||[]).map(persona=>`<option value="${esc(persona.id)}" ${persona.id===selected?"selected":""}>${esc(persona.name)} · @${esc(persona.handle)}</option>`).join("");
}

function governanceSetupRequired(message){
  app.innerHTML=`<div class="card"><h2>Platform governance setup required</h2><p class="muted">${esc(message||"Migration 051 has not been applied to this environment. No publication, role, security, follow, sync, or review setting was changed.")}</p><div class="gov-actions" style="margin-top:12px"><button class="btn sec" onclick="go('studio')">Back to Matrix</button></div></div>`;
}

async function governanceMaybe(table,query){
  try{const result=await query(sb.from(table));return result.error?{data:null,error:result.error}:{data:result.data,error:null}}catch(error){return{data:null,error}}
}

async function governanceRpc(name,args){
  try{const result=await sb.rpc(name,args);return result.error?{data:null,error:result.error}:{data:result.data,error:null}}catch(error){return{data:null,error}}
}

async function governanceLoad(personaId){
  const persona=governancePersona(personaId);if(!persona)return{error:new Error("Create a persona first")};
  const owner=session?.user?.id,epoch=renderEpoch;governanceState.personaId=persona.id;
  const readiness=await sb.rpc("persona_publication_readiness",{p_persona_id:persona.id});
  if(epoch!==renderEpoch||session?.user?.id!==owner)return{cancelled:true};
  if(readiness.error)return{error:readiness.error};
  const assigned=(myAccounts||[]).filter(account=>account.persona_id===persona.id||(myAccountPersonaLinks||[]).some(link=>link.ledger_id===account.id&&link.persona_id===persona.id));
  const [review,features,sync,friend,extensions,roles,security,relationships,familyEdges,projectMembers,businessMembers,revenueSettings,affiliateProducts,affiliateOffers,productReviewSettings,productReviewRequests,productReviewEvents,productReviewEvidence]=await Promise.all([
    governanceMaybe("persona_publication_reviews",q=>q.select("*").eq("persona_id",persona.id).maybeSingle()),
    governanceMaybe("platform_feature_requests",q=>q.select("*").eq("persona_id",persona.id).order("updated_at",{ascending:false}).limit(100)),
    governanceMaybe("persona_account_sync_settings",q=>q.select("*").eq("persona_id",persona.id)),
    governanceMaybe("persona_friend_settings",q=>q.select("*").eq("persona_id",persona.id).maybeSingle()),
    governanceMaybe("persona_extension_submissions",q=>q.select("id,owner,persona_id,title,source_type,requested_permissions,status,review_notes,submitted_at,reviewed_at,created_at,updated_at").eq("persona_id",persona.id).order("updated_at",{ascending:false}).limit(100)),
    governanceMaybe("platform_role_assignments",q=>q.select("role_key,active,expires_at,reason").eq("account_id",owner)),
    governanceMaybe("account_security_states",q=>q.select("password_failed_count,mfa_failed_count,locked_until,lock_reason,notification_pending,updated_at").eq("user_id",owner).maybeSingle()),
    governanceRpc("my_persona_family",{p_persona_id:persona.id}),
    governanceMaybe("persona_family_relationships",q=>q.select("id,from_persona_id,to_persona_id,relationship_type,visibility,canon_status,source_key,owner_notes,created_at,updated_at").or(`from_persona_id.eq.${persona.id},to_persona_id.eq.${persona.id}`).order("created_at")),
    governanceMaybe("persona_project_memberships",q=>q.select("*,persona_projects(*)").eq("persona_id",persona.id)),
    governanceMaybe("business_persona_memberships",q=>q.select("*,businesses(*)").eq("persona_id",persona.id)),
    governanceMaybe("persona_revenue_settings",q=>q.select("*").eq("persona_id",persona.id).maybeSingle()),
    governanceMaybe("affiliate_products",q=>q.select("*").eq("owner",owner).order("updated_at",{ascending:false}).limit(500)),
    governanceMaybe("persona_affiliate_offers",q=>q.select("*").eq("persona_id",persona.id).order("priority",{ascending:false}).limit(200)),
    governanceMaybe("product_review_settings",q=>q.select("*").eq("persona_id",persona.id).maybeSingle()),
    governanceMaybe("product_review_requests",q=>q.select("id,persona_id,requester_email,requester_name,product_name,product_url,reason,consent_to_reply,marketing_consent,status,created_at,updated_at,retention_expires_at").eq("persona_id",persona.id).order("created_at",{ascending:false}).limit(200)),
    governanceMaybe("product_review_events",q=>q.select("id,request_id,event_type,actor_type,details,created_at").eq("persona_id",persona.id).not("request_id","is",null).order("created_at",{ascending:false}).limit(500)),
    governanceRpc("my_product_review_notification_evidence",{p_persona_id:persona.id})
  ]);
  if(epoch!==renderEpoch||session?.user?.id!==owner)return{cancelled:true};
  governanceState={...governanceState,personaId:persona.id,readiness:readiness.data,review:review.data||null,reviewManifest:readiness.data?.review_manifest||null,featureRequests:features.data||[],syncSettings:sync.data||[],friendSettings:friend.data||null,extensions:extensions.data||[],roles:roles.data||[],security:security.data||null,relationships:relationships.data||[],familyEdges:familyEdges.data||[],projects:projectMembers.data||[],businesses:businessMembers.data||[],revenueSettings:revenueSettings.data||null,affiliateProducts:affiliateProducts.data||[],affiliateOffers:affiliateOffers.data||[],productReviewSettings:productReviewSettings.data||null,productReviewRequests:productReviewRequests.data||[],productReviewEvents:productReviewEvents.data||[],productReviewEvidence:productReviewEvidence.data||[],assignedAccounts:assigned,intentionPlan:null,intentionAiExplanation:"",capabilities:{governance:true,organization:!relationships.error&&!familyEdges.error&&!projectMembers.error&&!businessMembers.error,revenue:!revenueSettings.error&&!affiliateProducts.error&&!affiliateOffers.error&&!productReviewSettings.error,reviewInbox:!productReviewRequests.error&&!productReviewEvents.error&&!productReviewEvidence.error}};
  return{persona};
}

function governancePicker(route,persona){
  return `<select class="gov-persona-picker" aria-label="Persona" onchange="go('${route}/'+this.value)">${governancePersonaOptions(persona.id)}</select>`;
}

function governanceStateLabel(persona){
  const state=persona.publication_state||governanceState.readiness?.publication_state||"setup required";
  return `<span class="gov-state ${esc(state)}">${esc(state.replaceAll("_"," "))}</span>`;
}

function governanceChecklistHtml(){
  const checks=governanceState.readiness?.checks||[];
  return `<div class="gov-checklist">${checks.map(check=>`<div class="gov-check ${check.ok?"ok":""}"><span><b>${esc(check.label||check.key)}</b><small>${check.required?"Required before publication":"Recommended"}</small></span></div>`).join("")||'<p class="muted">No checklist was returned.</p>'}</div>`;
}

function governanceKnownGaps(){
  const gaps=[];
  if(!governanceState.capabilities.organization)gaps.push("Family, project, and business organization storage is not available in this environment.");
  if(governanceState.friendSettings?.request_mode==="contact_proof")gaps.push("Private email/phone acquaintance proof needs a server-side one-time proof service; the current mode fails closed.");
  if((governanceState.syncSettings||[]).some(row=>row.enabled))gaps.push("At least one account-sync preference is enabled, but each provider still needs a scoped import/export worker and reconciliation proof.");
  if((governanceState.extensions||[]).some(row=>["submitted","reviewing","approved"].includes(row.status)))gaps.push("Custom extension source still needs a sandboxed build, permission/CSP review, signing, and a staff-controlled release before it can run.");
  if(governanceState.revenueSettings?.review_requests_enabled&&!governanceState.productReviewSettings?.enabled)gaps.push("The public review-request preference is on, but a connected persona Gmail destination and hardened intake approval are still required.");
  if(governanceState.revenueSettings?.affiliate_enabled&&!(governanceState.affiliateOffers||[]).some(row=>row.status==="active"))gaps.push("Affiliate presentation is enabled, but this persona has no active product offer.");
  return gaps;
}

function governanceIntentionCatalog(){
  const organizationReady=!!governanceState.capabilities.organization;
  const requiredMissing=Number(governanceState.readiness?.required_missing||0);
  const pageBuilderReady=typeof openPersonaPageBuilder==="function";
  const linkedAccounts=(governanceState.assignedAccounts||[]).length;
  const readyModels=typeof readyAgentBackends==="function"?readyAgentBackends():[];
  const activeOffers=(governanceState.affiliateOffers||[]).filter(row=>row.status==="active").length;
  const contactProofSelected=governanceState.friendSettings?.request_mode==="contact_proof";
  return [
    {key:"publication",label:"Profile review and publication",match:/\b(page|profile|publish|public|launch|website|audience|bio|brand)\b/i,state:requiredMissing?"setup":"ready",summary:requiredMissing?`The publication workflow is built, but ${requiredMissing} required readiness item${requiredMissing===1?" is":"s are"} still missing for this persona.`:"Draft, exact-revision review, disclosure, readiness checks, and explicit publish/unpublish controls are built and the current required checks are complete.",steps:["Complete required profile fields and disclosure.","Run the exact-revision review.","Publish only the persona you have approved."]},
    {key:"page_builder",label:"Page layout, widgets, and reusable code",match:/\b(layout|design|designer|widget|wix|myspace|html|css|code|background|color|format|function|snippet|box)\b/i,state:pageBuilderReady?"limited":"blocked",summary:pageBuilderReady?"The visual layout editor, text/link custom boxes, styles, and private reusable snippets are built. Free-canvas Wix parity, live GUI-to-code translation, AI code lessons, and a public function market are not yet built.":"The page-builder entry point is unavailable in this environment.",steps:pageBuilderReady?["Open Page designer from Edit or Persona settings.","Arrange modules and custom field boxes, then save the draft layout.","Use private snippets for reviewed code; do not run untrusted uploaded code."]:["Deploy the matching page-builder frontend before configuring a layout."]},
    {key:"family",label:"Family relationships and connected family tree",match:/\b(family|parent|child|children|sibling|brother|sister|partner|spouse|tree|relative|relationship)\b/i,state:organizationReady?"ready":"blocked",summary:organizationReady?"Owner-managed parent, child, and partner edges with canon and visibility controls are built; sibling relationships are derived from shared parents.":"The organization migration is not available in this environment.",steps:organizationReady?["Add direct relationships in Persona settings.","Set each edge's public, friends-only, or owner-only visibility.","Enable the Family page module when you want approved public edges displayed."]:["Apply and verify the organization schema before entering family data."]},
    {key:"business",label:"Projects, groups, managers, and business roles",match:/\b(business|company|organization|project|group|manager|spokesperson|mission|team|castleborn|wais)\b/i,state:organizationReady?"limited":"blocked",summary:organizationReady?"Project and business records, memberships, titles, bios, visibility, and manager relationships have storage and owner settings. The editor does not yet expose every project-resource operation or a complete public business-page designer.":"Project and business storage is unavailable in this environment.",steps:organizationReady?["Create or select the business/project record.","Assign the persona's optional title and visibility.","Review the business page separately before publication."]:["Apply and verify the organization schema."]},
    {key:"accounts",label:"Attached account handles and feed sync preferences",match:/\b(social|account|handle|instagram|facebook|twitter|youtube|tiktok|linkedin|sync|repost|feed)\b/i,state:linkedAccounts?"limited":"setup",summary:linkedAccounts?`${linkedAccounts} assigned account record${linkedAccounts===1?" is":"s are"} visible. Scoped sync preferences are built, but each provider still needs a reviewed server worker and reconciliation evidence before data moves.`:"No account record is assigned to this persona yet; provider keys must remain server-side.",steps:["Confirm the handle and granted scopes in Edit or Persona settings.","Keep sync off until the matching reviewed provider worker is deployed.","Review imported and outbound content before publication."]},
    {key:"friends",label:"Friends, follows, and acquaintance proof",match:/\b(friend|follow|follower|community|fan|network|invite|acquaintance)\b/i,state:contactProofSelected?"limited":"ready",summary:contactProofSelected?"Follow and friend-request flows are built, but direct email/phone contact matching is intentionally unavailable. Expiring owner-issued invite proof is the safe current option.":"Public follows, mutual friend requests, rate limits, inbox caps, and expiring owner invite proof are built.",steps:["Choose open, invite-proof, or closed friend requests.","Use one-time invite proof when requests should be limited to known people.","Do not expose or compare private contact values in the browser."]},
    {key:"revenue",label:"Affiliate offers and transparent review requests",match:/\b(affiliate|product|review|recommend|revenue|monetize|income|shop|merchant)\b/i,state:activeOffers&&governanceState.productReviewSettings?.enabled?"limited":"setup",summary:"Disclosure-first affiliate and review-request records are built. An active reviewed offer, secure intake, verified notification destination, and provider-specific delivery evidence are still required per persona.",steps:["Connect the persona's reviewed notification destination.","Add the product, merchant destination, disclosure, and evidence.","Activate only after the public presentation and retention settings pass review."]},
    {key:"payments",label:"Payments and checkout",match:/\b(payment|payments|checkout|subscription|donation|tip|stripe|paypal|purchase|buy|sell)\b/i,state:"blocked",summary:"No production payment processor, merchant account, webhook ledger, refund flow, tax configuration, or checkout is built.",steps:["Choose the legal merchant of record and payout account.","Create a sandbox provider project and webhook threat model.","Complete legal, tax, refund, dispute, and two-account checkout testing before activation."]},
    {key:"media",label:"Images, video, audio, and AI provenance",match:/\b(image|photo|video|music|audio|gallery|album|media|gif|watermark|background)\b/i,state:"limited",summary:"AI-use declarations and generated-media watermark/provenance controls are packaged for migration 060. Rich public media widgets remain disabled until delivery uses opaque asset identifiers instead of stable owner UUID paths.",steps:["Apply and verify migration 060 and the coordinated media functions.","Use owner-only preview/download while public delivery remains blocked.","Ship opaque asset delivery before enabling rich public media widgets."]},
    {key:"security",label:"Authentication, staff roles, and attack monitoring",match:/\b(security|mfa|2fa|sso|admin|administrator|technician|role|logging|monitor|error|attack|ddos|captcha|waf|recovery)\b/i,state:"limited",summary:"Database roles, AAL2 gates, authentication ledgers, owner error logs, and fail-closed controls are partly built. MFA/SSO recovery policy, SMTP, CAPTCHA, WAF/rate-limit operations, alerts, and independent live verification require provider configuration and runbooks.",steps:["Enroll and test MFA plus recovery using a non-owner account.","Configure SMTP, CAPTCHA, WAF/rate limits, and alert destinations outside the browser client.","Run signed-in two-account privacy and lockout/recovery tests."]},
    {key:"ai",label:"AI assistance and persona automation",match:/\b(ai|assistant|model|agent|automation|training|teach|suggest|brainstorm|translate)\b/i,state:readyModels.length?"limited":"setup",summary:readyModels.length?`${readyModels.length} hosted text model${readyModels.length===1?" is":"s are"} ready for owner-invoked assistance. AI output is advisory, consumes provider tokens, and never publishes or submits tickets automatically.`:"No hosted text model is currently ready; local deterministic planning still works without tokens.",steps:["Review the deterministic capability plan first.","Choose a linked model only if you consent to sending the sanitized plan to that provider.","Treat its explanation as a draft and approve every resulting change or ticket yourself."]},
    {key:"mobile",label:"Responsive mobile use and installable web access",match:/\b(mobile|phone|tablet|responsive|pwa|web app|ios|android)\b/i,state:"limited",summary:"Responsive layouts are built, but the current release still requires signed-in mobile browser QA across owner and unrelated-account roles before it is release-proven.",steps:["Test the signed-in owner flow on a real phone.","Test an unrelated account and a signed-out visitor.","Record viewport, browser, route, and any accessibility failures."]}
  ];
}

function governanceBuildIntentionPlan(value){
  const intention=String(value||"").trim(),catalog=governanceIntentionCatalog(),matched=catalog.filter(item=>item.key==="publication"||item.key==="security"||(intention&&item.match.test(intention)));
  const items=matched.length>2?matched:catalog.filter(item=>["publication","page_builder","security"].includes(item.key));
  return{version:1,intention_present:!!intention,items,unresolved:items.filter(item=>item.state!=="ready"),known_gaps:governanceKnownGaps()};
}

function governanceIntentionPlanText(plan){
  return (plan?.items||[]).map(item=>`${item.state.toUpperCase()} — ${item.label}\n${item.summary}\n${item.steps.map(step=>"- "+step).join("\n")}`).join("\n\n");
}

function governanceRenderIntentionPlan(){
  const target=document.getElementById("govIntentionPlan");if(!target)return;
  const plan=governanceBuildIntentionPlan(document.getElementById("govIntention")?.value||governanceState.review?.intention||"");governanceState.intentionPlan=plan;
  const stateLabel={ready:"Available",setup:"Setup required",limited:"Partially available",blocked:"Not built / release blocked"};
  target.innerHTML=`${plan.intention_present?"":'<div class="gov-note warn"><b>Add a page intention for a tailored match.</b> The core publication, page-design, and security requirements are shown below.</div>'}<div class="gov-list">${plan.items.map(item=>`<div class="gov-row"><div class="gov-row-head"><b>${esc(item.label)}</b><span class="gov-state ${item.state==="ready"?"published":item.state==="blocked"?"declined":"draft"}">${esc(stateLabel[item.state]||item.state)}</span></div><p>${esc(item.summary)}</p><ol>${item.steps.map(step=>`<li>${esc(step)}</li>`).join("")}</ol></div>`).join("")}</div>${plan.known_gaps.length?`<div class="gov-note warn"><b>Additional detected environment gaps</b><ul>${plan.known_gaps.map(gap=>`<li>${esc(gap)}</li>`).join("")}</ul></div>`:""}`;
  const explanation=document.getElementById("govIntentionAiResult");if(explanation)explanation.innerHTML=governanceState.intentionAiExplanation?`<div class="gov-note"><b>Advisory model explanation — not saved or submitted</b><pre class="gov-code">${esc(governanceState.intentionAiExplanation)}</pre></div>`:"";
}

function governanceIntentionChanged(){
  governanceState.intentionAiExplanation="";
  governanceReviewDirty();
  governanceRenderIntentionPlan();
}

async function governanceExplainIntentionWithAi(){
  const intention=document.getElementById("govIntention")?.value.trim()||"";if(!intention){toast("Enter the page intention first");return}
  const backendId=document.getElementById("govIntentionBackend")?.value||"",backend=(myBackends||[]).find(row=>row.id===backendId);if(!backend||!backendAgentReady(backend)){toast("Choose a ready hosted text model");return}
  const plan=governanceBuildIntentionPlan(intention),sanitizedIntention=governanceRedactExternalText(intention),host=governanceReviewHost(backend.base_url)||backend.provider||"the selected provider",uid=session?.user?.id,epoch=renderEpoch,personaId=governanceState.personaId;
  const stillCurrent=()=>session?.user?.id===uid&&renderEpoch===epoch&&governanceState.personaId===personaId&&(document.getElementById("govIntention")?.value.trim()||"")===intention;
  if(!confirm(`Send the sanitized page intention and deterministic capability plan to ${backend.name} (${host})? This uses that provider's tokens. The reply is advisory and will not save, publish, or submit a ticket.`))return;
  const button=document.getElementById("govIntentionAiButton");if(button){button.disabled=true;button.textContent="Explaining…"}
  try{
    const reply=await callAI(backend.id,[{role:"user",content:`SANITIZED PAGE INTENTION\n${sanitizedIntention}\n\nAUTHORITATIVE DETERMINISTIC CAPABILITY PLAN\n${governanceIntentionPlanText(plan)}`}],{mode:"owner_chat",purpose:"capability_explain"});
    if(!stillCurrent())return;
    governanceState.intentionAiExplanation=String(reply||"").slice(0,12000);governanceRenderIntentionPlan();toast("Advisory explanation ready — nothing was saved or submitted");
  }catch(error){if(stillCurrent())toast(error.message||"The model explanation failed")}
  finally{if(button?.isConnected&&document.getElementById("govIntentionAiButton")===button){button.disabled=false;button.textContent="Ask linked AI to explain plan"}}
}

function governancePrefillKnownGap(){
  const plan=governanceBuildIntentionPlan(document.getElementById("govIntention")?.value||""),gaps=[...plan.unresolved.map(item=>`${item.label} [${item.state}]: ${item.summary}`),...plan.known_gaps],title=document.getElementById("govFeatureTitle"),description=document.getElementById("govFeatureDescription");
  if(!title||!description)return;if(!gaps.length){toast("No deterministic platform gap was detected. Add any limitation found in your browser-AI review manually.");return}
  title.value="Complete missing capability for this persona";description.value=["Page intention:",document.getElementById("govIntention")?.value.trim()||"(not entered)","","Authoritative unresolved capability checks:",...gaps.map(value=>"- "+value),"","Expected behavior:","Implement the smallest secure capability, document permissions and recovery, test with unrelated accounts, and keep every external write owner-approved."].join("\n").slice(0,30000);description.focus();
}

function governanceRedactExternalText(value){
  return String(value??"")
    .replace(/-----BEGIN[\s\S]{0,200}?PRIVATE KEY-----[\s\S]*?-----END[\s\S]{0,80}?PRIVATE KEY-----/gi,"[REDACTED PRIVATE KEY]")
    .replace(/\b(?:bearer\s+)?(?:sk-[a-z0-9_-]{12,}|gh[pousr]_[a-z0-9]{20,}|AIza[a-z0-9_-]{20,}|xox[baprs]-[a-z0-9-]{12,})\b/gi,"[REDACTED CREDENTIAL]")
    .replace(/\b(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|client[_ -]?secret|password|authorization)\s*[:=]\s*[^\s,;]+/gi,"[REDACTED CREDENTIAL FIELD]")
    .replace(/https?:\/\/[^\s)\]}]+/gi,"[URL REDACTED FROM FREEFORM TEXT]")
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,"[REDACTED EMAIL]")
    .replace(/(?:\+?\d[\d ().-]{7,}\d)/g,"[REDACTED PHONE]")
    .replace(/\b[a-z0-9_\/-]{40,}\b/gi,"[REDACTED POSSIBLE TOKEN]");
}

function governanceReviewHost(value){try{const url=new URL(String(value||""));return ["http:","https:"].includes(url.protocol)?url.hostname:""}catch{return""}}

function governanceExternalReviewManifest(){
  const manifest=governanceState.reviewManifest||{},profile=manifest.profile||{},layout=manifest.layout||{};
  const clean=value=>governanceRedactExternalText(value),publicProfile={};
  for(const key of ["handle","name","tagline","bio","visibility","theme","topics","hashtags","title","focus","pet_project","ai_disclosure"])publicProfile[key]=clean(profile[key]||"");
  publicProfile.nsfw=!!profile.nsfw;publicProfile.modules=Object.fromEntries(
    ["live","music","about","fan_chat","links","top8","linked","family","revenue","albums","feed"]
      .map(key=>[key,profile.modules?.[key]!==false])
  );
  const fan=profile.fan_agent_configuration||{};publicProfile.fan_agent_configuration={
    purpose_configured:!!fan.purpose_configured,voice_configured:!!fan.voice_configured,
    audience_configured:!!fan.audience_configured,hard_rules_configured:!!fan.hard_rules_configured,
    backend_configured:!!fan.backend_configured,fan_chat_configured:!!fan.fan_chat_configured,
    configuration_sha256:/^[0-9a-f]{64}$/i.test(String(fan.configuration_sha256||""))?fan.configuration_sha256:""
  };
  const widgets=(Array.isArray(layout.widgets)?layout.widgets:[]).map(widget=>{
    const style={
      span:["half","full"].includes(widget?.span)?widget.span:"half",
      shape:["square","soft","round"].includes(widget?.shape)?widget.shape:"soft",
      tone:["default","theme","muted","glass"].includes(widget?.tone)?widget.tone:"default"
    };
    return widget?.kind==="link"
      ?{kind:"link",title:clean(widget.title||""),body:clean(widget.body||""),label:clean(widget.label||""),destination_host:governanceReviewHost(widget.url),...style}
      :{kind:"text",title:clean(widget?.title||""),body:clean(widget?.body||""),...style};
  });
  return{
    schema_version:manifest.schema_version||1,revision:manifest.revision||0,complete:!!manifest.complete,
    counts:manifest.counts||{},truncation_reasons:manifest.truncation_reasons||[],profile:publicProfile,
    assets:(manifest.assets||[]).map(asset=>({label:clean(asset.label),kind:clean(asset.kind),configured:!!asset.url})),
    layout:{version:layout.version||1,order:Array.isArray(layout.order)?layout.order:[],cards:layout.cards||{},widgets},
    links:(manifest.links||[]).map(link=>({platform:clean(link.platform),handle:clean(link.handle),destination_host:governanceReviewHost(link.url)})),
    posts:(manifest.posts||[]).map(post=>({kind:clean(post.kind),title:clean(post.title),body:clean(post.body),tags:clean(post.tags),media_configured:!!post.media_url,created_at:post.created_at})),
    albums:(manifest.albums||[]).map(album=>({title:clean(album.title),kind:clean(album.kind),items:(album.items||[]).map(item=>({caption:clean(item.caption),image_configured:!!item.thumb_url,destination_host:governanceReviewHost(item.link_url)}))})),
    family:(manifest.family||[]).map(row=>({relationship:clean(row.relationship),handle:clean(row.handle),name:clean(row.name),image_configured:!!row.avatar_url})),
    top8:(manifest.top8||[]).map(row=>({handle:clean(row.handle),name:clean(row.name),tagline:clean(row.tagline||""),image_configured:!!row.avatar_url})),
    linked_personas:(manifest.linked_personas||[]).map(row=>({handle:clean(row.handle),name:clean(row.name),tagline:clean(row.tagline||""),image_configured:!!row.avatar_url})),
    revenue:{
      settings:{
        affiliate_enabled:!!manifest.revenue?.settings?.affiliate_enabled,
        review_requests_enabled:!!manifest.revenue?.settings?.review_requests_enabled,
        secure_request_intake_configured:!!manifest.revenue?.settings?.secure_request_intake_configured,
        default_disclosure:clean(manifest.revenue?.settings?.default_disclosure||""),
        cta_label:clean(manifest.revenue?.settings?.cta_label||""),
        review_cta_label:clean(manifest.revenue?.settings?.review_cta_label||"")
      },
      offers:(manifest.revenue?.offers||[]).map(offer=>({
        title:clean(offer.title),merchant:clean(offer.merchant),category:clean(offer.category),
        disclosure:clean(offer.disclosure),cta_label:clean(offer.cta_label),
        placement:clean(offer.placement),priority:Number(offer.priority)||0,
        product_host:governanceReviewHost(offer.product_url),
        affiliate_destination_host:governanceReviewHost(offer.affiliate_destination),
        image_configured:!!offer.image_url
      }))
    },
    withheld:manifest.withheld||[]
  };
}

function governanceReviewPacket(){
  const persona=governancePersona(),review=governanceState.review,checks=governanceState.readiness?.checks||[],manifest=governanceExternalReviewManifest();
  return [
    `MYPERSONAS SANITIZED PAGE REVIEW — ${governanceRedactExternalText(persona?.name||"Persona")} (@${governanceRedactExternalText(persona?.handle||"")})`,
    `Publication state: ${persona?.publication_state||governanceState.readiness?.publication_state||"unknown"}\nManifest revision: ${manifest.revision}\nManifest hash: ${governanceState.readiness?.manifest_sha256||"unavailable"}`,
    `Page intention (scanned/redacted):\n${governanceRedactExternalText(document.getElementById("govIntention")?.value||review?.intention||"")}`,
    `AI disclosure (scanned/redacted):\n${governanceRedactExternalText(document.getElementById("govDisclosure")?.value||persona?.ai_disclosure||"")}`,
    "Readiness:",...checks.map(item=>`- ${item.ok?"READY":"MISSING"}: ${item.label}${item.required?" (required)":" (recommended)"}`),
    "Sanitized exact-revision manifest (asset URLs and full outbound paths omitted):",JSON.stringify(manifest,null,2),
    "Review request:","Review for canon fidelity, privacy, transparent AI disclosure, accessibility, security, broken links, missing setup, and claims that require evidence. Return proposed edits only; do not publish or connect any external account."
  ].join("\n\n");
}

function governanceReviewManifestHtml(){
  const manifest=governanceState.reviewManifest;if(!manifest)return'<p class="muted">No review manifest was returned.</p>';
  const reasons=(manifest.truncation_reasons||[]).filter(Boolean),assets=(manifest.assets||[]).filter(asset=>safeHttpUrl(asset.url));
  return `<div class="gov-note ${manifest.complete?"":"stop"}"><b>Revision ${Number(manifest.revision||0)} manifest: ${manifest.complete?"complete":"incomplete"}.</b> ${reasons.map(esc).join(" · ")}</div><div class="gov-actions">${assets.map(asset=>`<button class="btn sec sm" data-owner-persona-id="${esc(governanceState.personaId)}" data-persona-asset-url="${esc(safeHttpUrl(asset.url))}" data-persona-asset-label="${esc(asset.label)}" data-persona-asset-kind="${esc(asset.kind)}" onclick="openPersonaAssetPreview(this,event)">Preview ${esc(asset.label)}</button>`).join("")}</div><details><summary>Inspect exact owner-only manifest JSON</summary><pre class="gov-code">${esc(JSON.stringify(manifest,null,2))}</pre></details>`;
}

function governanceFeatureSourceContext(){
  const readiness=governanceState.readiness||{},manifest=governanceState.reviewManifest||{};
  return{
    persona_id:governanceState.personaId||null,
    publication_state:readiness.publication_state||null,
    publication_revision:Number(readiness.publication_revision||0),
    required_missing:Number(readiness.required_missing||0),
    checks:(readiness.checks||[]).slice(0,30).map(item=>({key:String(item.key||"").slice(0,80),required:!!item.required,ok:!!item.ok})),
    warnings:(readiness.warnings||[]).slice(0,20).map(value=>String(value||"").slice(0,500)),
    review_manifest:{hash:readiness.manifest_sha256||null,complete:!!manifest.complete,counts:manifest.counts||{},truncation_reasons:(manifest.truncation_reasons||[]).slice(0,20).map(value=>String(value||"").slice(0,500))},
    intention_plan:{version:Number(governanceState.intentionPlan?.version||1),items:(governanceState.intentionPlan?.items||[]).slice(0,20).map(item=>({key:String(item.key||"").slice(0,80),state:String(item.state||"").slice(0,40)}))}
  };
}

